package cn.zj.zjmarket.test.payment;
import cn.zj.zjmarket.domain.payment.adapter.port.*;
import cn.zj.zjmarket.domain.payment.adapter.repository.ISettlementRepository;
import cn.zj.zjmarket.domain.payment.model.valobj.*;
import cn.zj.zjmarket.domain.payment.service.impl.SettlementService;
import cn.zj.zjmarket.domain.order.service.impl.OrderService;
import cn.zj.zjmarket.infrastructure.gateway.mq.*;
import cn.zj.zjmarket.infrastructure.gateway.codec.ContractCodec;
import cn.zj.zjmarket.infrastructure.config.properties.MqSettings;
import cn.zj.zjmarket.domain.product.model.valobj.SyncBadMessage;
import cn.zj.zjmarket.domain.product.adapter.repository.IProductSyncRepository;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class SettlementTests {
 static final String SECRET="public-payment-test-secret";
 static final String PAYMENT="""
 {"eventId":"receipt","eventType":"EVENT_PROCESSING_RESULT","schemaVersion":1,"producer":"group-buy-market","occurredAt":"2026-10-10T00:00:00.000Z","source":"s01","channel":"c01","correlationId":"original","payload":{"originalEventId":"original","originalEventType":"PAYMENT_SUCCEEDED","outcome":"APPLIED","code":"0000","info":"ok","processedAt":"2026-10-10T00:00:00.000Z","result":{"orderId":"a-order","outTradeNo":"order","teamId":"team","payment":{"paymentId":"payment","paidAmount":"9.00","currency":"CNY","paidAt":"2026-10-10T00:00:00.000Z"},"orderStatus":"PAID","teamStatus":"FORMING","recordVersion":"2","teamVersion":"3"}}}
 """;
 MqSettings settings;ISettlementRepository repo;TradeMessageReader reader;
 @BeforeEach void setup(){settings=new MqSettings();settings.setResultTopic("results");settings.setTeamTopic("teams");settings.setSource("s01");settings.setChannel("c01");repo=mock(ISettlementRepository.class);reader=new TradeMessageReader(settings,repo,Map.of("key",SECRET));}
 SyncBadMessage signed(String body,String topic,String tag)throws Exception{byte[] b=body.getBytes(StandardCharsets.UTF_8);return new SyncBadMessage(topic,tag,"key",ContractCodec.hmac(SECRET,topic+"\n"+ContractCodec.sha256(b)),b,null);}
 @Test void validPaymentCarriesOriginalWireHash()throws Exception{var m=signed(PAYMENT,"results","EVENT_PROCESSING_RESULT");var r=reader.decode(m);assertEquals("original",r.originalEventId());assertEquals(ContractCodec.sha256(m.body()),r.hash());reader.receive(m);verify(repo).receive(r);}
 @Test void malformedAndConflictingFieldsAreQuarantined()throws Exception{for(String raw:List.of(PAYMENT.replace("9.00","9.0"),PAYMENT.replace("CNY","USD"),PAYMENT.replace("\"paymentId\":\"payment\"","\"paymentId\":\"payment\",\"extra\":1"),PAYMENT.replace("\"schemaVersion\":1","\"schemaVersion\":1,\"schemaVersion\":1"),PAYMENT.replace("\"correlationId\":\"original\"","\"correlationId\":\"different\""),PAYMENT.replace("\"recordVersion\":\"2\"","\"recordVersion\":\"9223372036854775808\""))){assertThrows(RuntimeException.class,()->reader.decode(signed(raw,"results","EVENT_PROCESSING_RESULT")));}verifyNoInteractions(repo);}
 @Test void invalidSignatureCannotSupplyFact()throws Exception{var m=signed(PAYMENT,"results","EVENT_PROCESSING_RESULT");reader.receive(new SyncBadMessage(m.topic(),m.tag(),m.keyId(),"invalid",m.body(),null));verify(repo).quarantine(any(),eq("results"),eq("EVENT_PROCESSING_RESULT"),eq("key"),eq("invalid"),eq(m.body()),eq("SIGNATURE_INVALID"));verify(repo,never()).receive(any());}
 @Test void quarantineFailurePropagatesAndPreventsAck()throws Exception{doThrow(new IllegalStateException()).when(repo).quarantine(any(),any(),any(),any(),any(),any(),any());var m=signed(PAYMENT,"results","EVENT_PROCESSING_RESULT");assertThrows(IllegalStateException.class,()->reader.receive(new SyncBadMessage(m.topic(),m.tag(),m.keyId(),"invalid",m.body(),null)));}
 @Test void productConsumerIntentionallyRoutesValidPaymentAway()throws Exception{var store=mock(IProductSyncRepository.class);var products=new SyncResultReader(settings,store,Map.of("key",SECRET));assertTrue(products.receive(signed(PAYMENT,"results","EVENT_PROCESSING_RESULT")));verifyNoInteractions(store);}
 @Test void rejectedRequiresExplicitNullAndNonSuccessCode()throws Exception{var tree=new com.fasterxml.jackson.databind.ObjectMapper().readTree(PAYMENT);var p=(com.fasterxml.jackson.databind.node.ObjectNode)tree.get("payload");p.put("outcome","REJECTED");p.put("code","E0113");p.putNull("result");assertNotNull(reader.decode(signed(tree.toString(),"results","EVENT_PROCESSING_RESULT")));p.put("code","0000");assertThrows(RuntimeException.class,()->reader.decode(signed(tree.toString(),"results","EVENT_PROCESSING_RESULT")));}
 @Test void teamFullRosterAndSubsetValidated()throws Exception{String raw=PAYMENT.substring(0,PAYMENT.indexOf("\"payload\":"))+"\"payload\":{\"teamId\":\"team\",\"activityId\":\"1\",\"teamVersion\":\"3\",\"outTradeNoList\":[\"order\"],\"reconciliationId\":\"recon\",\"reason\":\"TARGET_NOT_REACHED\",\"refundRequiredOutTradeNoList\":[\"order\"]}}";raw=raw.replace("EVENT_PROCESSING_RESULT","TEAM_FAILED");assertNotNull(reader.decode(signed(raw,"teams","TEAM_FAILED")));final String bad=raw.replace("\"refundRequiredOutTradeNoList\":[\"order\"]","\"refundRequiredOutTradeNoList\":[\"foreign\"]");assertThrows(RuntimeException.class,()->reader.decode(signed(bad,"teams","TEAM_FAILED")));}
 @Test void notificationCommitFailureNeverAcknowledges(){var channel=mock(IChannelFacts.class);var transport=mock(ISettlementTransport.class);var n=new ChannelNotice("notice","payment","attempt","body",OrderService.hash("body"),"token",new Channel("payment","attempt","SUCCEEDED","transaction","9.00","CNY",1L),1);var f=new ChannelFact(new Channel("payment","attempt","SUCCEEDED","transaction","9.00","CNY",1L),"snapshot","request","PAID","attempt",0,2);when(channel.notices(20)).thenReturn(List.of(n));when(channel.fact("payment","attempt")).thenReturn(f);doThrow(new IllegalStateException()).when(repo).observe(f);new SettlementService(repo,channel,transport).tick(20);verify(channel,never()).acknowledge(any(),anyBoolean());}
 @Test void publishedBrokerAckAloneDoesNotSetAcceptance(){var channel=mock(IChannelFacts.class);var transport=mock(ISettlementTransport.class);var w=new TradeDelivery("event","payment","order","user","wire","hash","READY",0,"token");when(repo.claim()).thenReturn(w,null);new SettlementService(repo,channel,transport).tick(20);verify(transport).publish(w);verify(repo).delivered(w,true,null);verify(repo,never()).receive(any());}
 @Test void queryCompensationPrecedesRepublish(){var channel=mock(IChannelFacts.class);var transport=mock(ISettlementTransport.class);var w=new TradeDelivery("event","payment","order","user","wire","hash","PUBLISHED",0,"token");var receipt=new TradeReceipt("A","receipt","EVENT_PROCESSING_RESULT","hash","wire","event");when(repo.claim()).thenReturn(w,null);when(transport.query(w)).thenReturn(receipt);new SettlementService(repo,channel,transport).tick(20);verify(repo).receive(receipt);verify(transport,never()).publish(any());verify(transport,never()).queryTrade(any());}

 @Test void originalReadyPaymentPublishesEvenWhenAIsOffline(){var channel=mock(IChannelFacts.class);var transport=mock(ISettlementTransport.class);var w=new TradeDelivery("event","payment","order","user","same-original-wire","hash","READY",0,"token");when(repo.claim()).thenReturn(w,null);new SettlementService(repo,channel,transport).tick(20);verify(transport).publish(w);verify(transport,never()).query(any());verify(repo).delivered(w,true,null);}
 @Test void lostSendResponseUsesOriginalWireDuringQueryOutage(){var channel=mock(IChannelFacts.class);var transport=mock(ISettlementTransport.class);var w=new TradeDelivery("event","payment","order","user","same-original-wire","hash","READY",1,"token");when(repo.claim()).thenReturn(w,null);when(transport.query(w)).thenThrow(new IllegalStateException());new SettlementService(repo,channel,transport).tick(20);verify(transport).publish(w);verify(repo).delivered(w,true,null);verify(repo,never()).receive(any());}
}
